if __name__ == '__main__':
    env = OekoEnv(render_mode="ansi")
    env = OekoAuxRewardWrapper(env, scaling=0.1)
    env = OekoActionBuilderWrapper(env, auxilary_reward=False)
    obs, _ = env.reset()

    env.render()
    accumulated_reward = 0.0
    for a in action_history_300:
        obs, rew, terminated, truncated, info = env.step(a)
        accumulated_reward += rew

    env.render()
    log.info(f"{obs=}, {rew=}, {terminated=}, {truncated=}")
    log.info(f"Final info: \n{pprint.pformat(info)}")
    log.info(f"Final accumulated reward: {accumulated_reward}")